            StopAndDisposePlayer(ref player);

            using MemoryStream wav_ms = new(IO.ReadData(filePath, blobsetHeaderData.MainFinalOffSet, (int)blobsetHeaderData.MainUnCompressedSize));

            WavHeader wav_header = new(0, 0);
