    public class ZSTD_IO
    {
        /// 
        /// Decompresses data from a byte array and returns it.
        /// 
        /// Input Byte array.
        /// Is the data compressed.
        /// Returns uncompressed byte array.
        /// 
        /// [Wouldubeinta]		08/07/2025	Created
        /// 
        public static byte[] DecompressAndRead(byte[] input, bool isCompressed)
        {
            Decompressor? decompressor = null;
            byte[]? buffer = null;

            try
            {
                if (isCompressed)
                {
                    decompressor = new();
                    buffer = decompressor.Unwrap(input).ToArray();
                }
                else
                {
                    buffer = input;
                }
            }
            catch (Exception ex)
            {
                MessageBox.Show($"Error occurred, report it to Wouldy : {ex.Message}", "Hmm, something stuffed up :(", MessageBoxButtons.OK, MessageBoxIcon.Stop);
            }
            finally
            {
                if (decompressor != null) { decompressor.Dispose(); decompressor = null; }
            }
            return buffer;
        }

        /// 
        /// Decompresses chunk and writes the data.
        /// 
        /// Binary Reader input.
        /// Filestream writer
        /// 
        /// [Wouldubeinta]	26/07/2025	Created
        /// 
        public static void DecompressChunk(Reader br, FileStream writer)
        {
            while (br.Position < br.Length)
            {
                int compressedSize = br.ReadInt32();
                int tmp = compressedSize -= 4;
                compressedSize = tmp;

                bool isCompressed = true;

                byte[] dataChunk = br.ReadBytes(compressedSize);

                byte[] ZstdMagicArray = [dataChunk[0], dataChunk[1], dataChunk[2], dataChunk[3]];
                uint ZstdMagic = BitConverter.ToUInt32(ZstdMagicArray);

                if (ZstdMagic != 4247762216)
                    isCompressed = false;

                DecompressAndWrite(dataChunk, writer, isCompressed);
            }
        }

        /// 
        /// Compresses data from a byte array and returns it.
        /// 
        /// Input Byte array.
        /// Returns compressed byte array.
        /// 
        /// [Wouldubeinta]		08/07/2025	Created
        /// 
        public static byte[] CompressAndRead(byte[] input)
        {
            byte[]? buffer = null;
            Compressor? compressor = null;

            try
            {
                compressor = new();
                compressor.SetParameter(ZstdSharp.Unsafe.ZSTD_cParameter.ZSTD_c_dictIDFlag, 1);
                compressor.SetParameter(ZstdSharp.Unsafe.ZSTD_cParameter.ZSTD_c_contentSizeFlag, 0);
                compressor.SetParameter(ZstdSharp.Unsafe.ZSTD_cParameter.ZSTD_c_compressionLevel, 3);
                buffer = compressor.Wrap(input).ToArray();
            }
            catch (Exception ex)
            {
                MessageBox.Show($"Error occurred, report it to Wouldy : {ex.Message}", "Hmm, something stuffed up :(", MessageBoxButtons.OK, MessageBoxIcon.Stop);
            }
            return buffer;
        }

        /// 
        /// Decompresses the compressed chunk data, if compressed. Then writes appending chunk data to a file.
        /// 
        /// byte[] array chunk data.
        /// FileStream writer.
        /// Is the data compressed
        /// 
        /// [Wouldubeinta]		30/06/2025	Created
        /// 
        public static void DecompressAndWrite(byte[] input, FileStream writer, bool isCompressed)
        {
            Decompressor? decompressor = null;

            try
            {
                if (isCompressed)
                {
                    decompressor = new();
                    byte[] buffer = decompressor.Unwrap(input).ToArray();
                    writer.Write(buffer, 0, buffer.Length);
                    writer.Flush();
                }
                else
                {
                    writer.Write(input, 0, input.Length);
                    writer.Flush();
                }
            }
            catch (Exception ex)
            {
                MessageBox.Show($"Error occurred, report it to Wouldy : {ex.Message}", "Hmm, something stuffed up :(", MessageBoxButtons.OK, MessageBoxIcon.Stop);
            }
            finally
            {
                if (decompressor != null) { decompressor.Dispose(); decompressor = null; }
            }
        }

        /// 
        /// Compresses chunk data and appends to output file.
        /// 
        /// Byte array to be compressed.
        /// FileStream output writer.
        /// Compressed chunk offset.
        /// Data chunk size.
        /// Returns compressed chunk size.
        /// 
        /// [Wouldubeinta]		13/07/2025	Created
        /// 
        public static int CompressAndWrite(byte[] data, FileStream writer, ref int offset, int chunkSize = 262144)
        {
            MemoryStream? stream = null;
            Compressor? compressor = null;
            int compressedSize = 0;

            try
            {
                stream = new(data);
                compressor = new();
                compressor.SetParameter(ZstdSharp.Unsafe.ZSTD_cParameter.ZSTD_c_dictIDFlag, 1);
                compressor.SetParameter(ZstdSharp.Unsafe.ZSTD_cParameter.ZSTD_c_contentSizeFlag, 0);
                compressor.SetParameter(ZstdSharp.Unsafe.ZSTD_cParameter.ZSTD_c_compressionLevel, 4);

                int readCount = 0;
                byte[]? buffer = new byte[chunkSize];

                while ((readCount = stream.Read(buffer, 0, chunkSize)) != 0)
                {
                    offset = (int)writer.Position;
                    byte[]? output = compressor.Wrap(buffer).ToArray();
                    writer.Write(output, 0, output.Length);
                    writer.Flush();
                    compressedSize = output.Length;
                }
            }
            catch (Exception ex)
            {
                MessageBox.Show($"Error occurred, report it to Wouldy : {ex.Message}", "Hmm, something stuffed up :(", MessageBoxButtons.OK, MessageBoxIcon.Stop);
            }
            finally
            {
                if (stream != null) { stream.Dispose(); stream = null; }
                if (compressor != null) { compressor.Dispose(); compressor = null; }
            }
            return compressedSize;
        }

        /// 
        /// Compresses chunk data and appends to output file.
        /// 
        /// Byte array to be compressed.
        /// FileStream output writer.
        /// Data chunk size.
        /// 
        /// [Wouldubeinta]		14/07/2025	Created
        /// 
        public static void CompressAndWrite(byte[] data, FileStream writer, int chunkSize = 262144)
        {
            Compressor? compressor = null;

            try
            {
                compressor = new();
                compressor.SetParameter(ZstdSharp.Unsafe.ZSTD_cParameter.ZSTD_c_dictIDFlag, 1);
                compressor.SetParameter(ZstdSharp.Unsafe.ZSTD_cParameter.ZSTD_c_contentSizeFlag, 0);
                compressor.SetParameter(ZstdSharp.Unsafe.ZSTD_cParameter.ZSTD_c_compressionLevel, 4);

                byte[]? output = compressor.Wrap(data).ToArray();

                if (output.Length < chunkSize)
                {
                    writer.Write(BitConverter.GetBytes(output.Length + 4), 0, 4);
                    writer.Write(output, 0, output.Length);
                    writer.Flush();
                }
                else
                {
                    writer.Write(BitConverter.GetBytes(data.Length + 4), 0, 4);
                    writer.Write(data, 0, data.Length);
                    writer.Flush();
                }
            }
            catch (Exception ex)
            {
                MessageBox.Show($"Error occurred, report it to Wouldy : {ex.Message}", "Hmm, something stuffed up :(", MessageBoxButtons.OK, MessageBoxIcon.Stop);
            }
            finally
            {
                if (compressor != null) { compressor.Dispose(); compressor = null; }
            }
        }

        /// 
        /// Decompresses the compressed chunk data, if compressed. Then read's the headers magic to determine the file type.
        /// 
        /// byte[] array chunk data.
        /// Is the data compressed
        /// 
        /// [Wouldubeinta]		01/07/2025	Created
        /// 
        public static int DecompressAndReadMagic(byte[] input, bool isCompressed)
        {
            Decompressor? decompressor = null;
            int magic = 0;
            byte[]? buffer = null;
            bool isMiniTXPK = false;

            try
            {
                if (isCompressed)
                {
                    decompressor = new();
                    buffer = decompressor.Unwrap(input).ToArray();

                    if (buffer.AsSpan(20, 4).SequenceEqual("conv"u8))  // checking for "conv" string
                        isMiniTXPK = true;
                }
                else
                    buffer = input;

                byte[] tmp = new byte[4];

                if (isMiniTXPK)
                {
                    tmp[0] = 77; tmp[1] = 73; tmp[2] = 78; tmp[3] = 73; // setting the magic to "MINI"
                }
                else
                {
                    tmp[0] = buffer[0]; tmp[1] = buffer[1]; tmp[2] = buffer[2]; tmp[3] = buffer[3];
                }

                magic = BitConverter.ToInt32(tmp);
            }
            catch (Exception ex)
            {
                MessageBox.Show($"Error occurred, report it to Wouldy : {ex.Message}", "Hmm, something stuffed up :(", MessageBoxButtons.OK, MessageBoxIcon.Stop);
            }
            finally
            {
                if (decompressor != null) { decompressor.Dispose(); decompressor = null; }
            }
            return magic;
        }

        /// 
        /// M3MP Decompress extracts all the files from a decompressed tmp m3mp file.
        /// 
        /// Temporary m3mp file path.
        /// Output folder location.
        /// 
        /// [Wouldubeinta]		30/06/2025	Created
        /// 
        public static void M3MPDecompressAndWrite(string m3mpTempFile, string folderPath, BackgroundWorker? bgw = null)
        {
            FileStream? fsReader = null;
            FileStream? fsWriter = null;
            Reader? br = null;

            try
            {
                string m3mp_uncompressed_data = Path.Combine(Global.currentPath, "temp", "m3mp_uncompressed_data.tmp");

                if (File.Exists(m3mp_uncompressed_data))
                    File.Delete(m3mp_uncompressed_data);

                fsReader = new(m3mpTempFile, FileMode.Open, FileAccess.Read, FileShare.ReadWrite);
                br = new(fsReader);

                M3MP m3mp = new();
                m3mp.Deserialize(br);

                fsWriter = new(m3mp_uncompressed_data, FileMode.Append, FileAccess.Write, FileShare.ReadWrite);

                for (int i = 0; i < m3mp.ChunksCount; i++)
                {
                    br.Position = m3mp.CompressedEntries[i].CompressedDataInfo.Offset;

                    byte[] compressedChunkData = br.ReadBytes((int)m3mp.CompressedEntries[i].CompressedDataInfo.CompressedSize);
                    DecompressAndWrite(compressedChunkData, fsWriter, true);

                    int percentProgress = (i + 1) * 100 / (int)m3mp.ChunksCount;
                    bgw.ReportProgress(percentProgress, "Extracting Chunk Data - " + (i + 1).ToString());
                }

                if (fsWriter != null) { fsWriter.Dispose(); fsWriter = null; }
                if (br != null) { br.Close(); br = null; }

                int index = 0;
                br = new(m3mp_uncompressed_data);

                foreach (var entry in m3mp.UnCompressedEntries)
                {
                    string filePath = entry.FilePath.Replace("/", @"\");
                    string outputFilePath = folderPath + filePath;
                    Directory.CreateDirectory(Path.GetDirectoryName(outputFilePath));

                    int chunkCount = Utilities.ChunkAmount((int)m3mp.UnCompressedEntries[index].UncompressedDataInfo.Size);
                    long[] chunkSizes = Utilities.ChunkSizes((int)m3mp.UnCompressedEntries[index].UncompressedDataInfo.Size, chunkCount);

                    fsWriter = new(outputFilePath, FileMode.Append, FileAccess.Write, FileShare.ReadWrite);

                    for (int i = 0; i < chunkCount; i++)
                    {
                        byte[] tmpData = br.ReadBytes((int)chunkSizes[i]);
                        IO.ReadWriteData(tmpData, fsWriter, (int)chunkSizes[i]);
                    }

                    int percentProgress = (index + 1) * 100 / (int)m3mp.FilesCount;
                    bgw.ReportProgress(percentProgress, filePath);
                    index++;
                    if (fsWriter != null) { fsWriter.Dispose(); fsWriter = null; }
                }

                if (br != null) { br.Close(); br = null; }
                if (fsWriter != null) { fsWriter.Dispose(); fsWriter = null; }

                if (File.Exists(m3mp_uncompressed_data))
                    File.Delete(m3mp_uncompressed_data);
            }
            catch (Exception ex)
            {
                MessageBox.Show($"Error occurred, report it to Wouldy : {ex.Message}", "Hmm, something stuffed up :(", MessageBoxButtons.OK, MessageBoxIcon.Stop);
            }
            finally
            {
                if (br != null) { br.Close(); br = null; }
                if (fsWriter != null) { fsWriter.Dispose(); fsWriter = null; }
                if (fsReader != null) { fsReader.Dispose(); fsReader = null; }
            }
        }

        /// 
        /// Get's TXPK header info.
        /// 
        /// File path to txpk.
        /// Returns the txpk header info.
        /// 
        /// [Wouldubeinta]		30/06/2025	Created
        /// 
        public static TXPK ReadTXPKInfo(string fileIn)
        {
            Reader? input = null;
            Reader? txpk_br = null;
            TXPK? txpk = null;

            try
            {
                //uint MainCompressedSize = Global.blobsetHeaderData.Entries[Global.filelist[Global.fileIndex].BlobsetIndex].MainCompressedSize;
                uint MainCompressedSize = Global.blobsetHeaderData.Entries[Array.FindIndex(Global.blobsetHeaderData.Entries, item => item.FileHashName == Global.filelist[Global.fileIndex].FileHash)].MainCompressedSize;
                uint MainUnCompressedSize = Global.blobsetHeaderData.Entries[Global.filelist[Global.fileIndex].BlobsetIndex].MainUnCompressedSize;

                input = new(fileIn);

                if (MainCompressedSize != MainUnCompressedSize)
                {
                    int txpkCompressedChunkSize = input.ReadInt32();
                    int txpkTmp = txpkCompressedChunkSize -= 4;
                    txpkCompressedChunkSize = txpkTmp;

                    bool isTxpkCompressed = true;

                    byte[] txpkData = input.ReadBytes(txpkCompressedChunkSize);

                    byte[] ZstdMagicArray = [txpkData[0], txpkData[1], txpkData[2], txpkData[3]];
                    uint ZstdMagic = BitConverter.ToUInt32(ZstdMagicArray);

                    if (ZstdMagic != 4247762216)
                        isTxpkCompressed = false;

                    byte[] txpkHeader = DecompressAndRead(txpkData, isTxpkCompressed);

                    txpk_br = new(txpkHeader);

                    txpk = new();
                    txpk.Deserialize(txpk_br);
                }
                else
                {
                    txpk = new();
                    txpk.Deserialize(input);
                }
            }
            catch (Exception ex)
            {
                MessageBox.Show($"Error occurred, report it to Wouldy : {ex.Message}", "Hmm, something stuffed up :(", MessageBoxButtons.OK, MessageBoxIcon.Stop);
            }
            finally
            {
                if (input != null) { input.Close(); input = null; }
                if (txpk_br != null) { txpk_br.Close(); txpk_br = null; }
            }
            return txpk;
        }

        /// 
        /// Get's M3MP header info.
        /// 
        /// File path to m3mp.
        /// Is the M3MP compressed.
        /// Returns the m3mp header info.
        /// 
        /// [Wouldubeinta]		08/07/2025	Created
        /// 
        public static M3MP ReadM3MPInfo(string fileIn, bool isCompressed)
        {
            Reader? input = null;
            Reader? m3mp_br = null;
            M3MP? m3mp = null;

            try
            {
                if (!File.Exists(fileIn))
                    return m3mp;

                input = new(fileIn);
                m3mp = new();

                if (isCompressed)
                {
                    List m3mpHeaderChunk = new(3);
                    int m3mpHeaderSize = 0;

                    for (int j = 0; j < 3; j++)
                    {
                        int m3mpCompressedSize = input.ReadInt32();
                        int m3mpTmp = m3mpCompressedSize -= 4;
                        m3mpCompressedSize = m3mpTmp;

                        bool isM3mpCompressed = true;

                        byte[] m3mpData = input.ReadBytes(m3mpCompressedSize);

                        byte[] ZstdMagicArray = [m3mpData[0], m3mpData[1], m3mpData[2], m3mpData[3]];
                        uint ZstdMagic = BitConverter.ToUInt32(ZstdMagicArray);

                        if (ZstdMagic != 4247762216)
                            isM3mpCompressed = false;

                        m3mpHeaderChunk.Add(DecompressAndRead(m3mpData, isM3mpCompressed));
                        m3mpHeaderSize += 262144;
                    }

                    byte[] m3mpHeader = IO.CombineDataChunks(m3mpHeaderChunk, m3mpHeaderSize);
                    m3mp_br = new Reader(m3mpHeader);
                    m3mp.Deserialize(m3mp_br);
                }
                else
                    m3mp.Deserialize(input);
            }
            catch (Exception ex)
            {
                MessageBox.Show($"Error occurred, report it to Wouldy : {ex.Message}", "Hmm, something stuffed up :(", MessageBoxButtons.OK, MessageBoxIcon.Stop);
            }
            finally
            {
                if (input != null) { input.Close(); input = null; }
                if (m3mp_br != null) { m3mp_br.Close(); m3mp_br = null; }
            }
            return m3mp;
        }
    }
}

﻿using Blobset_Tools;
using PackageIO;
using static Blobset_Tools.Enums;

namespace BlobsetIO
{
    /// 
    /// Blobset File Class.
    /// 
    /// 
    ///   Blobset Tools. Written by Wouldubeinta
    ///   Copyright (C) 2026 Wouldy Mods.
    ///   
    ///   This program is free software; you can redistribute it and/or
    ///   modify it under the terms of the GNU General Public License
    ///   as published by the Free Software Foundation; either version 3
    ///   of the License, or (at your option) any later version.
    ///   
    ///   This program is distributed in the hope that it will be useful,
    ///   but WITHOUT ANY WARRANTY; without even the implied warranty of
    ///   MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the
    ///   GNU General Public License for more details.
    ///   
    ///   You should have received a copy of the GNU General Public License
    ///   along with this program; if not, write to the Free Software
    ///   Foundation, Inc., 59 Temple Place - Suite 330, Boston, MA  02111-1307, USA.
    /// 
    ///   The author may be contacted at:
    ///   Discord: Wouldubeinta
    /// 
    /// 
    /// [Wouldubeinta]	   02/06/2025	Created
    /// 
    public class BlobsetFile
    {
        #region Fields
        private byte[]? sHA1Hash = new byte[20]; // only used in older games
        private uint magic = 0; // Should be  - BLOB or BOLB
        private uint blobsetCount = 0;
        private uint filesCount = 0;
        private Entry[]? entries;
        #endregion

        public BlobsetFile()
        {
            entries = null;
        }

        public class Entry
        {
            public string FolderHashName = string.Empty;
            public string FileHashName = string.Empty;

            public uint FileIndex = 0;

            public uint MainFinalOffSet = 0;
            public uint MainCompressedSize = 0;
            public uint MainUnCompressedSize = 0;
            public uint VramFinalOffSet = 0;
            public uint VramCompressedSize = 0;
            public uint VramUnCompressedSize = 0;
            public uint BlobSetNumber = 0;
        }

        #region Properties
        public byte[] SHA1Hash
        {
            get { return sHA1Hash; }
            set { sHA1Hash = value; }
        }

        public uint Magic
        {
            get { return magic; }
            set { magic = value; }
        }

        public uint BlobsetCount
        {
            get { return blobsetCount; }
            set { blobsetCount = value; }
        }

        public uint FilesCount
        {
            get { return filesCount; }
            set { filesCount = value; }
        }

        public Entry[]? Entries
        {
            get { return entries; }
            set { entries = value; }
        }
        #endregion

        #region "Deserialize"
        /// 
        /// Deserialize Blobset stream
        /// 
        /// Blobset input stream
        /// Blobset Version
        public void Deserialize(Reader input, Enums.BlobsetVersion blobsetVersion)
        {
            int gameId = Global.gameInfo.GameId;
            Endian endian = Endian.Little;

            if (Global.isBigendian)
                endian = Endian.Big;

            input.CurrentEndian = endian;

            if (gameId > 0 && gameId < 8 && gameId != 5)
                SHA1Hash = input.ReadBytes(20, Endian.Little);

            Magic = input.ReadUInt32();

            if (Magic != 1112493122) // BLOB or BOLB // if (Magic != 1112493122 && Magic != 1112297282)
            {
                MessageBox.Show("This isn't a Blobset File", "Wrong Magic", MessageBoxButtons.OK, MessageBoxIcon.Error);
                return;
            }

            if (blobsetVersion != Enums.BlobsetVersion.v3 && blobsetVersion != Enums.BlobsetVersion.v4)
                BlobsetCount = input.ReadUInt32();

            FilesCount = input.ReadUInt32();

            Entries = new Entry[FilesCount];

            for (int i = 0; i < FilesCount; i++)
            {
                Entries[i] = new Entry();

                if (blobsetVersion == Enums.BlobsetVersion.v4)
                {
                    ulong fileFolderHashName = input.ReadUInt64();
                    byte[] intBytes = BitConverter.GetBytes(fileFolderHashName);
                    string folderName = string.Format("{0:x2}", intBytes[7]);
                    string fileName = string.Format("{0:x2}{1:x2}{2:x2}{3:x2}{4:x2}{5:x2}{6:x2}", intBytes[6], intBytes[5], intBytes[4], intBytes[3], intBytes[2], intBytes[1], intBytes[0]);
                    Entries[i].FolderHashName = folderName;
                    Entries[i].FileHashName = fileName;
                }
                else if (blobsetVersion == Enums.BlobsetVersion.v1 || blobsetVersion == Enums.BlobsetVersion.v2)
                {
                    Entries[i].MainFinalOffSet = input.ReadUInt32();
                    Entries[i].MainCompressedSize = input.ReadUInt32();
                    Entries[i].MainUnCompressedSize = input.ReadUInt32();
                    Entries[i].VramFinalOffSet = input.ReadUInt32();
                    Entries[i].VramCompressedSize = input.ReadUInt32();
                    Entries[i].VramUnCompressedSize = input.ReadUInt32();
                    uint fileFolderHashName = input.ReadUInt32();
                    byte[] intBytes = BitConverter.GetBytes(fileFolderHashName);
                    string folderName = string.Format("{0:x2}", intBytes[3]);
                    string fileName = string.Format("{0:x2}{1:x2}{2:x2}", intBytes[2], intBytes[1], intBytes[0]);
                    Entries[i].FolderHashName = folderName;
                    Entries[i].FileHashName = fileName;
                    Entries[i].BlobSetNumber = input.ReadUInt32();
                }
                else
                {
                    Entries[i].MainCompressedSize = input.ReadUInt32();
                    Entries[i].MainUnCompressedSize = input.ReadUInt32();
                    Entries[i].VramCompressedSize = input.ReadUInt32();
                    Entries[i].VramUnCompressedSize = input.ReadUInt32();
                    uint fileFolderHashName = input.ReadUInt32();
                    byte[] intBytes = BitConverter.GetBytes(fileFolderHashName);
                    string folderName = string.Format("{0:x2}", intBytes[3]);
                    string fileName = string.Format("{0:x2}{1:x2}{2:x2}", intBytes[2], intBytes[1], intBytes[0]);
                    input.ReadUInt32();
                    Entries[i].FolderHashName = folderName;
                    Entries[i].FileHashName = fileName;
                }
            }

            if (blobsetVersion == Enums.BlobsetVersion.v4)
            {
                for (int i = 0; i < FilesCount; i++)
                {
                    Entries[i].MainCompressedSize = input.ReadUInt32();
                    Entries[i].MainUnCompressedSize = input.ReadUInt32();
                    Entries[i].VramCompressedSize = input.ReadUInt32();
                    Entries[i].VramUnCompressedSize = input.ReadUInt32();
                }
            }
        }
        #endregion

        #region "WBST_Deserialize"
        /// 
        /// Deserialize Wouldys Blobset Tools Table stream
        /// 
        /// Input stream
        public void WBST_Deserialize(Reader input) 
        {
            Magic = input.ReadUInt32();

            if (Magic != 1414742615) // WBST
            {
                MessageBox.Show("This isn't a Wouldys Blobset Tools Table File", "Wrong Magic", MessageBoxButtons.OK, MessageBoxIcon.Error);
                return;
            }

            FilesCount = input.ReadUInt32();

            Entries = new Entry[FilesCount];

            for (int i = 0; i < FilesCount; i++) 
            {
                Entries[i] = new Entry();

                Entries[i].FileIndex = input.ReadUInt32();
                ulong fileFolderHashName = input.ReadUInt64();
                byte[] intBytes = BitConverter.GetBytes(fileFolderHashName);
                string folderName = string.Format("{0:x2}", intBytes[7]);
                string fileName = string.Format("{0:x2}{1:x2}{2:x2}{3:x2}{4:x2}{5:x2}{6:x2}", intBytes[6], intBytes[5], intBytes[4], intBytes[3], intBytes[2], intBytes[1], intBytes[0]);
                Entries[i].FolderHashName = folderName;
                Entries[i].FileHashName = fileName;
                Entries[i].MainCompressedSize = input.ReadUInt32();
                Entries[i].MainUnCompressedSize = input.ReadUInt32();
                Entries[i].VramCompressedSize = input.ReadUInt32();
                Entries[i].VramUnCompressedSize = input.ReadUInt32();
            }
        }
        #endregion

        #region "Serialize"
        /// 
        /// Serialize Blobset stream v4
        /// 
        /// Blobset output stream
        public void Serialize(Writer output)
        {
            output.WriteUInt32(1414742615); // WBST
            output.WriteUInt32(FilesCount);

            for (int i = 0; i < FilesCount; i++)
            {
                output.WriteUInt32(Entries[i].FileIndex);
                output.WriteHexString(Entries[i].FolderHashName);
                output.WriteHexString(Entries[i].FileHashName);
                output.WriteUInt32(Entries[i].MainCompressedSize);
                output.WriteUInt32(Entries[i].MainUnCompressedSize);
                output.WriteUInt32(Entries[i].VramCompressedSize);
                output.WriteUInt32(Entries[i].VramUnCompressedSize);
            }
        }
        #endregion
    }
}

﻿using Blobset_Tools;
using PackageIO;

namespace BlobsetIO
{
    /// 
    /// M3MP Class.
    /// 
    /// 
    ///   Blobset Tools. Written by Wouldubeinta
    ///   Copyright (C) 2026 Wouldy Mods.
    ///   
    ///   This program is free software; you can redistribute it and/or
    ///   modify it under the terms of the GNU General Public License
    ///   as published by the Free Software Foundation; either version 3
    ///   of the License, or (at your option) any later version.
    ///   
    ///   This program is distributed in the hope that it will be useful,
    ///   but WITHOUT ANY WARRANTY; without even the implied warranty of
    ///   MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the
    ///   GNU General Public License for more details.
    ///   
    ///   You should have received a copy of the GNU General Public License
    ///   along with this program; if not, write to the Free Software
    ///   Foundation, Inc., 59 Temple Place - Suite 330, Boston, MA  02111-1307, USA.
    /// 
    ///   The author may be contacted at:
    ///   Discord: Wouldubeinta
    /// 
    /// 
    /// [Wouldubeinta]	   01/06/2025	Created
    /// 
    public class M3MP
    {
        #region Fields
        private uint magic = 0; // Should be  - M3MP
        private uint filesCount = 0;
        private uint chunksCount = 0;
        private uint compressedDataOffset = 0;
        private UnCompressedEntry[]? uncompressedEntries;
        private CompressedEntry[]? compressedEntries;
        #endregion

        public M3MP()
        {
            uncompressedEntries = null;
            compressedEntries = null;
        }

        public class UnCompressedEntry
        {
            public UncompressedDataInfo? UncompressedDataInfo;
            public string? FilePath;
        }

        public class CompressedEntry
        {
            public ChunkCompressedDataInfo? CompressedDataInfo;
        }

        #region Properties
        public uint Magic
        {
            get { return magic; }
            set { magic = value; }
        }

        public uint FilesCount
        {
            get { return filesCount; }
            set { filesCount = value; }
        }

        public uint ChunksCount
        {
            get { return chunksCount; }
            set { chunksCount = value; }
        }

        public uint CompressedDataOffset
        {
            get { return compressedDataOffset; }
            set { compressedDataOffset = value; }
        }

        public UnCompressedEntry[] UnCompressedEntries
        {
            get { return uncompressedEntries; }
            set { uncompressedEntries = value; }
        }

        public CompressedEntry[] CompressedEntries
        {
            get { return compressedEntries; }
            set { compressedEntries = value; }
        }
        #endregion

        public class UncompressedDataInfo
        {
            public uint Offset = 0;
            public uint Size = 0;
            public uint FilePathOffset = 0;
            public uint Reserved = 0; // Allways 0
        }

        public class ChunkCompressedDataInfo
        {
            public uint Offset = 0;
            public uint CompressedSize = 0;
            public uint UnCompressedSize = 0;
        }

        #region "Deserialize"
        /// 
        /// Deserialize M3MP stream
        /// 
        /// M3MP input stream
        public void Deserialize(Reader input)
        {
            Endian endian = Endian.Little;

            if (Global.isBigendian)
                endian = Endian.Big;

            input.CurrentEndian = endian;

            Magic = input.ReadUInt32();

            if (Magic != 1347236685) // M3MP
            {
                MessageBox.Show("This isn't a M3MP File", "Wrong Magic", MessageBoxButtons.OK, MessageBoxIcon.Error);
                return;
            }

            FilesCount = input.ReadUInt32();
            ChunksCount = input.ReadUInt32();
            CompressedDataOffset = input.ReadUInt32();

            UnCompressedEntries = new UnCompressedEntry[FilesCount];

            for (int i = 0; i < FilesCount; i++)
            {
                UnCompressedEntries[i] = new();
                UnCompressedEntries[i].UncompressedDataInfo = new();
                UnCompressedEntries[i].UncompressedDataInfo.Offset = input.ReadUInt32();
                UnCompressedEntries[i].UncompressedDataInfo.Size = input.ReadUInt32();
                UnCompressedEntries[i].UncompressedDataInfo.FilePathOffset = input.ReadUInt32();
                UnCompressedEntries[i].UncompressedDataInfo.Reserved = input.ReadUInt32();
            }

            for (int i = 0; i < FilesCount; i++)
            {
                UnCompressedEntries[i].FilePath = input.ReadNullTerminatedString();
            }

            CompressedEntries = new CompressedEntry[ChunksCount];

            for (int i = 0; i < ChunksCount; i++)
            {
                CompressedEntries[i] = new();
                CompressedEntries[i].CompressedDataInfo = new();
                CompressedEntries[i].CompressedDataInfo.Offset = input.ReadUInt32();
                CompressedEntries[i].CompressedDataInfo.CompressedSize = input.ReadUInt32();
                CompressedEntries[i].CompressedDataInfo.UnCompressedSize = input.ReadUInt32();
            }
        }
        #endregion

        #region "Serialize"
        /// 
        /// Serialize M3MP stream
        /// 
        /// M3MP output stream
        public void Serialize(Writer output)
        {
            Endian endian = Endian.Little;

            if (Global.isBigendian)
                endian = Endian.Big;

            output.CurrentEndian = endian;

            output.WriteUInt32(1347236685); // M3MP
            output.WriteUInt32(FilesCount);
            output.WriteUInt32(ChunksCount);
            output.WriteUInt32(CompressedDataOffset);

            for (int i = 0; i < FilesCount; i++)
            {
                output.WriteUInt32(UnCompressedEntries[i].UncompressedDataInfo.Offset);
                output.WriteUInt32(UnCompressedEntries[i].UncompressedDataInfo.Size);
                output.WriteUInt32(UnCompressedEntries[i].UncompressedDataInfo.FilePathOffset);
                output.WriteUInt32(UnCompressedEntries[i].UncompressedDataInfo.Reserved);
            }

            output.CurrentEndian = Endian.Little;

            for (int i = 0; i < FilesCount; i++)
            {
                UnCompressedEntries[i].UncompressedDataInfo.FilePathOffset = (uint)output.Position;
                output.WriteString(UnCompressedEntries[i].FilePath);
                output.WriteInt8(0);
            }

            output.CurrentEndian = endian;

            for (int i = 0; i < ChunksCount; i++)
            {
                output.WriteUInt32(CompressedEntries[i].CompressedDataInfo.Offset);
                output.WriteUInt32(CompressedEntries[i].CompressedDataInfo.CompressedSize);
                output.WriteUInt32(CompressedEntries[i].CompressedDataInfo.UnCompressedSize);
            }
        }
        #endregion
    }
}

