        {
            int blobsetIndex = 0;

            foreach (var blobsetHeaderDataEntries in Global.blobsetHeaderData.Entries)
            {
                if (blobsetHeaderDataEntries.FolderHashName == folderHash && blobsetHeaderDataEntries.FileHashName == fileHash)
                {
                    break;
                }
                blobsetIndex++;
