﻿namespace PackageIO
{
    public enum Endian
    {
        Big = 2,
        Little = 1
    }
}

﻿namespace PackageIO
{
    using System;
    using System.IO;
    using System.Text;
    using System.Text.RegularExpressions;

    public class Functions
    {
        public static bool CompareBytes(byte[] Arg0, byte[] Arg1)
        {
            return (Conversions.ObjectToHex(Arg0) == Conversions.ObjectToHex(Arg1));
        }

        public static int FileLen(string FilePath)
        {
            return FilePath.Length;
        }

        public static string GetDirectory(string filename)
        {
            return Path.GetDirectoryName(filename);
        }

        public static string GetRatio(long Arg0, long Arg1)
        {
            return (Convert.ToDouble(Arg0 / Arg1)).ToString() + "%";
        }

        public static bool IsNumeric(long Numeric)
        {
            return new Regex(@"^[0-9]+\d").IsMatch(Numeric.ToString());
        }

        public static bool IsValidHex(string Hex)
        {
            return new Regex("^[A-Fa-f0-9]*$", RegexOptions.IgnoreCase).IsMatch(Hex);
        }

        public static bool IsValidUnicode(string Unicode)
        {
            return (Unicode.Length == LenB(Unicode));
        }

        public static int LenB(string ObjStr)
        {
            if (ObjStr.Length == 0)
            {
                return 0;
            }
            return Encoding.Unicode.GetByteCount(ObjStr);
        }

        public static byte[] RemoveAt(byte[] Bytes, int Index)
        {
            return Conversions.HexToByteArray(Conversions.ObjectToHex(Bytes).Remove(Index, 2));
        }

        public static byte[] RemoveByte(byte[] Bytes, byte ByteToRemove)
        {
            return Conversions.HexToByteArray(Conversions.ObjectToHex(Bytes).Replace(ByteToRemove.ToString(), ""));
        }

        public static Array ReverseArray(Array Buffer)
        {
            Array.Reverse(Buffer);
            return Buffer;
        }

        public static string RoundBytes(long ByteCount)
        {
            if (ByteCount < 0x400)
            {
                return (ByteCount.ToString() + " b");
            }
            if ((ByteCount >= 0x400) && (ByteCount < 0x100000))
            {
                return (Convert.ToDouble(ByteCount / 1024.0).ToString() + " kb");
            }
            if ((ByteCount >= 0x100000) && (ByteCount < 0x40000000))
            {
                return (Convert.ToDouble(ByteCount / 1024.0 / 1024.0).ToString() + " mb");
            }
            if ((ByteCount < 0x40000000) || (ByteCount >= 0x10000000000))
            {
                throw new Exception("WTF!");
            }
            return (Convert.ToDouble(ByteCount / 1024.0 / 1024.0 / 1024.0).ToString() + " gb");
        }

        public static string FormatSize(ulong bytes)
        {
            string[] UNITS = new string[] { "B", "KB", "MB", "GB", "TB", "PB", "EB" };

            int c = 0;
            for (c = 0; c < UNITS.Length; c++)
            {
                ulong m = (ulong)1 << ((c + 1) * 10);
                if (bytes < m)
                    break;
            }

            double n = bytes / (double)((ulong)1 << (c * 10));
            return string.Format("{0:0.##} {1}", n, UNITS[c]);
        }

        public static byte[] SwapSex(byte[] Buffer)
        {
            return (byte[])ReverseArray(Buffer);
        }
    }
}

﻿namespace PackageIO
{
    using System.IO;
    using System.Runtime.InteropServices;

    public class IO
    {
        private PackageLayout Package;
        public Reader? Reader;
        public Writer? Writer;

        public IO(FileStream Package, Endian EndianType = (Endian)1, long Position = 0)
        {
            Reader = null;
            Writer = null;
            this.Package.Package = Package;
            this.Package.EndianType = EndianType;
            this.Package.Position = Position;
            Set(this.Package);
        }

        public IO(MemoryStream Package, Endian EndianType = (Endian)1, long Position = 0)
        {
            Reader = null;
            Writer = null;
            this.Package.Package = Package;
            this.Package.EndianType = EndianType;
            this.Package.Position = Position;
            Set(this.Package);
        }

        public IO(byte[] Package, Endian EndianType = (Endian)1, long Position = 0)
        {
            Reader = null;
            Writer = null;
            this.Package.Package = new MemoryStream(Package);
            this.Package.EndianType = EndianType;
            this.Package.Position = Position;
            Set(this.Package);
        }

        public IO(Stream Package, Endian EndianType = (Endian)1, long Position = 0)
        {
            Reader = null;
            Writer = null;
            this.Package.Package = Package;
            this.Package.EndianType = EndianType;
            this.Package.Position = Position;
            Set(this.Package);
        }

        public IO(string Package, Endian EndianType = (Endian)1, long Position = 0)
        {
            Reader = null;
            Writer = null;
            this.Package.Package = new FileStream(Package, FileMode.Open, FileAccess.ReadWrite, FileShare.ReadWrite);
            this.Package.EndianType = EndianType;
            this.Package.Position = Position;
            Set(this.Package);
        }

        public void Close()
        {
            Reader = null;
            Writer = null;
            Package.Package.Close();
            Package = new PackageLayout();
            Package.Package = Stream;
        }

        public long LastPosition(IOType Type)
        {
            if (Type == IOType.Writer)
            {
                return Writer.LastPosition;
            }
            return Reader.LastPosition;
        }

        private void Set(PackageLayout Value)
        {
            Reader = new Reader(Value.Package, Value.EndianType, Value.Position);
            Writer = new Writer(Value.Package, Value.EndianType, Value.Position);
        }

        public void SwapEndian()
        {
            if (CurrentEndian == Endian.Little)
            {
                CurrentEndian = Endian.Big;
            }
            else
            {
                CurrentEndian = Endian.Little;
            }
            Reader.CurrentEndian = CurrentEndian;
            Writer.CurrentEndian = CurrentEndian;
        }

        public Endian CurrentEndian
        {
            get
            {
                return Package.EndianType;
            }
            set
            {
                Package.EndianType = value;
                Reader.CurrentEndian = value;
                Writer.CurrentEndian = value;
            }
        }

        public long Length
        {
            get
            {
                return Package.Package.Length;
            }
        }

        public long Position
        {
            get
            {
                return Package.Position;
            }
            set
            {
                Package.Position = value;
                Reader.Position = value;
                Writer.Position = value;
            }
        }

        public Stream Stream
        {
            get
            {
                return Package.Package;
            }
            set
            {
                PackageLayout layout = new();
                if (value.Length <= Package.Position)
                {
                    layout.Position = Package.Position;
                }
                else
                {
                    layout.Position = 0;
                }
                Close();
                Package = layout;
                Set(Package);
            }
        }

        public enum IOType
        {
            Writer,
            Reader
        }

        [StructLayout(LayoutKind.Sequential)]
        private struct PackageLayout
        {
            public Stream Package;
            public Endian EndianType;
            public long Position;
        }
    }
}

﻿namespace PackageIO
{
    using System;
    using System.Collections.Generic;
    using System.IO;
    using System.Text;

    public class Reader : IDisposable
    {
        public Endian CurrentEndian;
        public long LastPosition;
        private readonly Stream? OpenStream;
        private readonly BinaryReader? br;

        // Track whether Dispose has already been called
        private bool _disposed = false;

        public Reader(FileStream Package, Endian EndianType = Endian.Little, long Position = 0)
        {
            OpenStream = null;
            br = null;
            LastPosition = 0;
            OpenStream = Package;
            br = new BinaryReader(OpenStream);
            this.Position = Position;
            CurrentEndian = EndianType;
        }

        public Reader(string Package, Endian EndianType = Endian.Little, long Position = 0)
        {
            OpenStream = null;
            br = null;
            LastPosition = 0;
            OpenStream = new FileStream(Package, FileMode.Open, FileAccess.ReadWrite, FileShare.ReadWrite);
            br = new BinaryReader(OpenStream);
            this.Position = Position;
            CurrentEndian = EndianType;
        }

        public Reader(byte[] Package, Endian EndianType = Endian.Little, long Position = 0)
        {
            OpenStream = null;
            br = null;
            LastPosition = 0;
            OpenStream = new MemoryStream(Package);
            br = new BinaryReader(OpenStream);
            this.Position = Position;
            CurrentEndian = EndianType;
        }

        public Reader(MemoryStream Package, Endian EndianType = Endian.Little, long Position = 0)
        {
            OpenStream = null;
            br = null;
            LastPosition = 0;
            OpenStream = Package;
            br = new BinaryReader(OpenStream);
            this.Position = Position;
            CurrentEndian = EndianType;
        }

        public Reader(Stream Package, Endian EndianType = Endian.Little, long Position = 0)
        {
            OpenStream = null;
            br = null;
            LastPosition = 0;
            OpenStream = Package;
            br = new BinaryReader(OpenStream);
            this.Position = Position;
            CurrentEndian = EndianType;
        }

        // Public Implementation of IDisposable
        public void Dispose()
        {
            Dispose(disposing: true);
            GC.SuppressFinalize(this);
        }

        // Protected implementation for extensibility in derived classes
        protected virtual void Dispose(bool disposing)
        {
            if (!_disposed)
            {
                if (disposing)
                {
                    // Clean up managed resources
                    Flush();
                    br?.Dispose();          // BinaryReader.Dispose() automatically closes the stream
                    OpenStream?.Dispose();  // Safeguard to ensure the stream is also disposed
                }

                _disposed = true;
            }
        }

